  icon?: undefined | IconName,

  /** The kind of button, from higher prominance to lower. */
  kind?: undefined | 'primary' | 'secondary' | 'tertiary',

  /**
   * Which visual variant to use. Default: 'normal'.
   */
  variant?: undefined | 'normal',

  /**
