  alt: true,
  autoCapitalize: true,
  autoComplete: true,
  autoFocus: true,
  capture: true,
  checked: true,
  defaultValue: true,
  disabled: true,
  form: true,
  formAction: true,
  formEncType: true,
  formMethod: true,
  formNoValidate: true,
  formTarget: true,
  height: true,
  list: true,
  max: true,
  maxLength: true,
  min: true,
  minLength: true,
  multiple: true,
  name: true,
  pattern: true,
  placeholder: true,
  readOnly: true,
  required: true,
  size: true,
  src: true,
  step: true,
  type: true,
  value: true,
  width: true,

