    subject,
    activateWith: (subject: S | (() => S)) => {
      // Use flushSync() to force the modal to render, in case the modal rendering is conditional
      // on the subject being set.
      flushSync(() => { setSubject(subject); });

      modalRef.current?.activate();
    },
    deactivate: () => {
