  const modal = useModalWithSubject({ subjectInitial });

  const handleConfirm = React.useCallback(() => {
    const subject = modal.subject;
    if (typeof subject === 'undefined') {
      console.error(`Unexpected: missing subject in confirmation`);
      return;
    }
    onConfirm(subject);
