// `<input/>` element. However, additionally we allow the following input-specific props as a convenience.

// 
// https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/input#attributes
export const inputSpecificPropKeys = {
  accept: true,
  alt: true,
  autoCapitalize: true,
  autoComplete: true,
  autoFocus: true,
  capture: true,
  checked: true,
  defaultValue: true,
  disabled: true,
  form: true,
  formAction: true,
  formEncType: true,
  formMethod: true,
  formNoValidate: true,
  formTarget: true,
  height: true,
  list: true,
  max: true,
  maxLength: true,
  min: true,
  minLength: true,
  multiple: true,
  name: true,
  pattern: true,
  placeholder: true,
  readOnly: true,
  required: true,
  size: true,
  src: true,
  step: true,
  type: true,
  value: true,
  width: true,

  // Form events
  onChange: true,
  onChangeCapture: true,
  onBeforeInput: true,
  onBeforeInputCapture: true,
  onInput: true,
  onInputCapture: true,
  onReset: true,
  onResetCapture: true,
  onSubmit: true,
  onSubmitCapture: true,
  onInvalid: true,
  onInvalidCapture: true,

